$editId=filter_var(query('edit'),FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]); $record=$editId?one("SELECT * FROM $table WHERE id=?",[$editId]):[]; if($editId&&!$record)missing();
if($_SERVER['REQUEST_METHOD']==='POST')try {
    $action=post('action');
    if($action==='delete') { confirmed(); $id=id_field('id'); if($table==='staff_accounts'&&$id==(int)$user['id'])throw new DomainException('You cannot delete your own account.'); transaction(function()use($table,$id){ if($table==='academic_terms'&&one("SELECT id FROM academic_terms WHERE id=? AND semester='unspecified'",[$id]))throw new DomainException('The historical term cannot be deleted.'); if($table==='curriculum_subjects'){$r=one('SELECT course_id,class_id FROM curriculum_subjects WHERE id=?',[$id]);if($r&&one('SELECT id FROM curriculum_subjects WHERE course_id=? AND prerequisite_class_id=? LIMIT 1',[$r['course_id'],$r['class_id']]))throw new DomainException('Remove dependent prerequisite mappings first.');} if(!execute("DELETE FROM $table WHERE id=?",[$id]))throw new DomainException('Record not found.'); audit('delete',"$table #$id"); }); }
    elseif(in_array($action,['create','update'],true)) {
        $id=$action==='update'?id_field('id'):null;
        if($id&&!one("SELECT id FROM $table WHERE id=?",[$id]))missing();
        transaction(function()use($table,$validate,$id){ $data=$validate($id); if($table==='classes'&&!empty($data['teacher_id'])){ $t=$data['teacher_id'];if(!one("SELECT id FROM staff_accounts WHERE id=? AND role='teacher' AND active=1 FOR UPDATE",[$t]))throw new DomainException('Choose an active teacher.');$assigned=rows('SELECT id FROM classes WHERE teacher_id=? AND term_id=? AND id<>? FOR UPDATE',[$t,$data['term_id'],$id??0]);if(count($assigned)>=3)throw new DomainException('A teacher may have at most three assigned subjects per term. Reassign another class first.'); } if($id){ $set=implode(',',array_map(fn($k)=>"$k=?",array_keys($data))); if($table==='staff_accounts' && (isset($data['password_hash']) || isset($data['role'])))$set.=',session_version=session_version+1'; execute("UPDATE $table SET $set WHERE id=?",[...array_values($data),$id]); } else { $keys=implode(',',array_keys($data)); $marks=implode(',',array_fill(0,count($data),'?')); execute("INSERT INTO $table ($keys) VALUES ($marks)",array_values($data)); $id=(int)db()->lastInsertId(); } audit('save',"$table #$id"); });
    } else deny();
    flash('Record saved successfully.'); redirect($page);
} catch(DomainException $ex){$error=$ex->getMessage();} catch(PDOException $ex){error_log_file($ex);$error=$ex->getCode()==='23000'?'Duplicate value or related records prevent this change. Remove dependencies first, or deactivate the account.':'Unable to save the record.';}
$q='%'.search_term().'%'; $data=rows($listSql,[$q,$q,...($listExtraParams??[])]);
